/**
 * Small (128x128), hand-drawn, black-and-white illustrated portraits -- the default art used by
 * `Avatar`'s `placeholder` prop when no real `src` is supplied yet. Each is ~7-8KB, embedded as a
 * data URI so the feature works with zero setup (no static-asset serving required) and adds only
 * ~80KB total to a bundle that actually uses it.
 *
 * Source art: `placeholders/avatar-*.{jpeg,webp}` at the repo root (originals, full resolution).
 */
export const AVATAR_PLACEHOLDERS: readonly string[] = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
];
